WITH filtered_employees AS (SELECT *, CAST(salary AS INT) AS salary_int FROM employees WHERE (hire_date >= '2025-02-01' AND full_name LIKE 'Dav%') OR manager_id IN (3, 4, 39)), summary AS (SELECT DATE_FORMAT(hire_date, 'yyyy-MM') AS hire_month, MIN(hire_date) AS first_hire_date FROM filtered_employees GROUP BY DATE_FORMAT(hire_date, 'yyyy-MM')) SELECT hire_month, first_hire_date FROM summary ORDER BY hire_month
